mapper.select:
/* selectMmsContentsInfoSeq - Lee JiSeob */
SELECT ISRY_SMS.MMS_CONTENTS_INFO_SEQ.NEXTVAL
FROM DUAL

mapper.insert:

/* insertLMS1 - Lee JiSeob */

INSERT INTO ISRY_SMS.MMS_CONTENTS_INFO
(
    CONT_SEQ, FILE_CNT, MMS_SUBJECT, MMS_BODY
) 
VALUES 
(
    #{mmsContentsInfoSeq}, 
    1, 
    #{title}, 
    #{contents}
)

mapper.select:
/* selectSmsHistory - Lee JiSeob */
SELECT (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_VALUE = X.SNDNG_STTS_SE_CD AND CMMNS_CD_ID = 'SNDNG_STTS_SE_CD' ) AS SNDNG_STTS_NM, X.SNDNG_STTS_SE_CD, X.USERDATA, X.MSG_SEQ, X.SUB_ID, X.CUR_STATE, X.SENT_DATE, X.RSLT_DATE, TO_CHAR(X.REQ_DATE, 'YYYY-MM-DD HH24:MI:SS') AS REQ_DATE, X.REQ_DATE_DD, X.RSLT_CODE, X.RSLT_CODE2, X.RSLT_NET, X.CALL_TO, X.CALL_FROM, X.SMS_TXT, X.MSG_TYPE, X.LMS_TXT, X.CONT_SEQ, X.USER_ID, X.USER_NAME
FROM ( SELECT CASE WHEN CUR_STATE = 0 THEN '00' WHEN CUR_STATE IN (1, 2) THEN '01' WHEN CUR_STATE = 3 AND RSLT_CODE = 100 THEN '03' WHEN CUR_STATE = 3 AND (RSLT_CODE > 100 OR RSLT_CODE IS NULL) THEN '02' END AS SNDNG_STTS_SE_CD, USERDATA, MSG_SEQ, SUB_ID, CUR_STATE, SENT_DATE, RSLT_DATE, REQ_DATE, TO_CHAR(REQ_DATE, 'YYYYMMDD') AS REQ_DATE_DD, RSLT_CODE, RSLT_CODE2, RSLT_NET, CALL_TO, CALL_FROM, SMS_TXT, MSG_TYPE, CASE WHEN MSG_TYPE = 6 THEN D.MMS_BODY ELSE '' END AS LMS_TXT, C.CONT_SEQ, C.USER_ID,
CASE WHEN E.ENFSN_NO IS NOT NULL THEN G.FLNM_ENCPT WHEN F.INST_NO IS NOT NULL THEN '____' || H.INST_NM WHEN E.YNGBGS_PRTCR_NO IS NOT NULL THEN I.FLNM_ENCPT ELSE '' END AS USER_NAME
FROM ISRY_SMS.MSG_LOG C
LEFT JOIN ISRY_SMS.MMS_CONTENTS_INFO D ON C.CONT_SEQ = D.CONT_SEQ
LEFT JOIN SAA200 E /* 사용자 */ ON E.USER_ID = C.USER_ID LEFT JOIN SAB230 F /* 사용자기관 */ ON F.USER_ID = E.USER_ID LEFT JOIN SCA100 G /* 종사자 */ ON G.ENFSN_NO = E.ENFSN_NO LEFT JOIN SAA000 H /* 통합기관 */ ON H.INST_NO = F.INST_NO LEFT JOIN SCA200 I /* 청소년보호자 */ ON I.YNGBGS_PRTCR_NO = E.YNGBGS_PRTCR_NO
WHERE
( C.USER_ID IS NULL OR C.USER_ID = 'system' ) OR ( F.INST_NO IN
#{item}
/* 종사자 */ AND G.ENFSN_NO = #{ENFSN_NO}
)
F.INST_NO IN
#{item}
/* 종사자 */ AND G.ENFSN_NO = #{ENFSN_NO}
ORDER BY REQ_DATE DESC
) X
AND X.USER_ID LIKE '%' || #{USER_ID} || '%'
AND (X.USER_NAME = #{USER_NAME_ENCPT} OR X.USER_NAME = '____' || #{USER_NAME})
AND X.CALL_TO LIKE '%' || #{CALL_TO} || '%'
AND X.CALL_FROM LIKE '%' || #{CALL_FROM} || '%'
AND X.REQ_DATE_DD = #{REQ_DATE_DD}
AND X.SNDNG_STTS_SE_CD = #{CMMNS_CD_VALUE}
OFFSET #{OFFSET_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY

/* selectSmsHistoryCount - Lee JiSeob */
SELECT COUNT(*) AS CNT
FROM ( SELECT USERDATA, MSG_SEQ, SUB_ID, CUR_STATE, SENT_DATE, RSLT_DATE, REQ_DATE, TO_CHAR(REQ_DATE, 'YYYYMM') AS REQ_DATE_MM, TO_CHAR(REQ_DATE, 'YYYYMMDD') AS REQ_DATE_DD, RSLT_CODE, RSLT_CODE2, RSLT_NET, CALL_TO, CALL_FROM, SMS_TXT, MSG_TYPE, CASE WHEN MSG_TYPE = 6 THEN D.MMS_BODY ELSE '' END AS LMS_TXT, C.CONT_SEQ, C.USER_ID,
CASE WHEN E.ENFSN_NO IS NOT NULL THEN G.FLNM_ENCPT WHEN F.INST_NO IS NOT NULL THEN '____' || H.INST_NM WHEN E.YNGBGS_PRTCR_NO IS NOT NULL THEN I.FLNM_ENCPT ELSE '' END AS USER_NAME
FROM ISRY_SMS.MSG_LOG C
LEFT JOIN ISRY_SMS.MMS_CONTENTS_INFO D ON C.CONT_SEQ = D.CONT_SEQ
LEFT JOIN SAA200 E /* 사용자 */ ON E.USER_ID = C.USER_ID LEFT JOIN SAB230 F /* 사용자기관 */ ON F.USER_ID = E.USER_ID LEFT JOIN SCA100 G /* 종사자 */ ON G.ENFSN_NO = E.ENFSN_NO LEFT JOIN SAA000 H /* 통합기관 */ ON H.INST_NO = F.INST_NO LEFT JOIN SCA200 I /* 청소년보호자 */ ON I.YNGBGS_PRTCR_NO = E.YNGBGS_PRTCR_NO
WHERE
( C.USER_ID IS NULL OR C.USER_ID = 'system' ) OR ( F.INST_NO IN
#{item}
/* 종사자 */ AND G.ENFSN_NO = #{ENFSN_NO}
)
F.INST_NO IN
#{item}
/* 종사자 */ AND G.ENFSN_NO = #{ENFSN_NO}
) X
AND X.USER_ID LIKE '%' || #{USER_ID} || '%'
AND (X.USER_NAME = #{USER_NAME_ENCPT} OR X.USER_NAME = '____' || #{USER_NAME})
AND X.CALL_TO LIKE '%' || #{CALL_TO} || '%'
AND X.CALL_FROM LIKE '%' || #{CALL_FROM} || '%'
AND X.REQ_DATE_DD = #{REQ_DATE_DD}
AND X.SNDNG_STTS_SE_CD = #{CMMNS_CD_VALUE}
